import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useI18n } from '../i18n/I18nContext.js';
import { apiRequest } from '../utils/api.js';
import { 
  Briefcase, 
  PlusCircle, 
  Trash2,
  FileText,
  Code,
  ListChecks,
  AlertCircle
} from 'lucide-react';

interface ChecklistItem {
  id: string;
  requirement: string;
  importance: 'Mandatory' | 'Important' | 'Additional';
}

export const Jobs: React.FC = () => {
  const { t } = useI18n();
  const navigate = useNavigate();

  // Basic Info fields
  const [title, setTitle] = useState('');
  const [department, setDepartment] = useState('');
  const [location, setLocation] = useState('');
  const [experience, setExperience] = useState(0);
  const [degree, setDegree] = useState('');
  const [specialization, setSpecialization] = useState('');

  // Merged single skills field (removes duplication of skills vs technicalSkills)
  const [skills, setSkills] = useState('');
  const [nationality, setNationality] = useState('');
  const [languages, setLanguages] = useState('');
  const [softSkills, setSoftSkills] = useState('');
  const [requiredCerts, setRequiredCerts] = useState('');
  const [jobDescription, setJobDescription] = useState('');
  const [coreResponsibilities, setCoreResponsibilities] = useState('');
  const [additionalRequirements, setAdditionalRequirements] = useState('');

  // Evaluation Checklist
  const [checklist, setChecklist] = useState<ChecklistItem[]>(() => [
    { id: 'req-1', requirement: t('defaultChecklistReq1'), importance: 'Mandatory' },
    { id: 'req-2', requirement: t('defaultChecklistReq2'), importance: 'Important' }
  ]);

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});

  // Auto-grow textarea handler
  const handleAutoGrow = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    e.target.style.height = 'auto';
    e.target.style.height = `${e.target.scrollHeight}px`;
  };

  const handleAddChecklistItem = () => {
    setChecklist([
      ...checklist,
      { id: 'req-' + Date.now(), requirement: '', importance: 'Important' }
    ]);
  };

  const handleRemoveChecklistItem = (id: string) => {
    setChecklist(checklist.filter(item => item.id !== id));
  };

  const handleChecklistTextChange = (id: string, text: string) => {
    setChecklist(checklist.map(item => item.id === id ? { ...item, requirement: text } : item));
  };

  const handleChecklistImportanceChange = (id: string, importance: any) => {
    setChecklist(checklist.map(item => item.id === id ? { ...item, importance } : item));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const errors: Record<string, string> = {};

    if (!title.trim()) errors.title = t('valJobTitleRequired');
    if (!department.trim()) errors.department = t('valDepartmentRequired');
    if (!location.trim()) errors.location = t('valLocationRequired');
    if (experience < 0 || isNaN(experience)) errors.experience = t('valExperienceRequired');
    if (!degree.trim()) errors.degree = t('valDegreeRequired');

    const invalidItems = checklist.some(item => !item.requirement.trim());
    if (invalidItems) {
      errors.checklist = t('emptyChecklistError');
    }

    if (Object.keys(errors).length > 0) {
      setFieldErrors(errors);
      return;
    }

    setFieldErrors({});
    setLoading(true);
    setError(null);

    try {
      const skillsArray = skills ? skills.split(',').map(s => s.trim()).filter(Boolean) : [];
      await apiRequest('POST', '/api/jobs', {
        title,
        department,
        location,
        experience,
        degree,
        skills: skillsArray,
        checklist,
        specialization,
        technicalSkills: skillsArray, // Map to backend for backwards compatibility
        nationality,
        languages,
        softSkills: softSkills ? softSkills.split(',').map(s => s.trim()).filter(Boolean) : [],
        requiredCerts,
        jobDescription,
        coreResponsibilities,
        additionalRequirements
      });
      navigate('/');
    } catch (err: any) {
      setError(err.message || t('failedEval'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto w-full px-4 md:px-6 py-6 space-y-6">
      {/* Page Header */}
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 rounded-2xl bg-brand/10 border border-brand/20 flex items-center justify-center text-brand shrink-0">
          <Briefcase className="w-5 h-5" />
        </div>
        <div className="text-start">
          <h2 className="text-xl font-black text-text-main">{t('createJob')}</h2>
          <p className="text-xs text-text-muted mt-0.5">{t('sectionBasicInfo')}</p>
        </div>
      </div>

      {/* General Validation Error Alert */}
      {error && (
        <div className="p-4 bg-red-500/10 border border-red-500/20 text-red-500 text-xs font-semibold rounded-2xl flex items-center gap-2 text-start">
          <AlertCircle className="w-4 h-4 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      {/* Main Form */}
      <form noValidate onSubmit={handleSubmit} className="space-y-6">

        {/* Section 1: Basic Info */}
        <div className="bg-bg-card border border-border-main p-6 rounded-2xl space-y-4 shadow-sm">
          <div className="flex items-center gap-2 pb-2 border-b border-border-main/50">
            <FileText className="w-4 h-4 text-brand" />
            <h3 className="text-xs font-bold text-text-muted uppercase tracking-wider">
              {t('sectionBasicInfo')}
            </h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Job Title */}
            <div>
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('jobTitle')} <span className="text-red-500 font-bold">*</span>
              </label>
              <input
                type="text"
                required
                aria-required="true"
                value={title}
                onChange={(e) => {
                  setTitle(e.target.value);
                  setFieldErrors(prev => ({ ...prev, title: '' }));
                }}
                placeholder={t('jobTitlePlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium transition-all"
              />
              {fieldErrors.title && (
                <p className="text-[11px] text-red-500 font-semibold mt-1 text-start">{fieldErrors.title}</p>
              )}
            </div>

            {/* Department */}
            <div>
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('department')} <span className="text-red-500 font-bold">*</span>
              </label>
              <input
                type="text"
                required
                aria-required="true"
                value={department}
                onChange={(e) => {
                  setDepartment(e.target.value);
                  setFieldErrors(prev => ({ ...prev, department: '' }));
                }}
                placeholder={t('departmentPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium transition-all"
              />
              {fieldErrors.department && (
                <p className="text-[11px] text-red-500 font-semibold mt-1 text-start">{fieldErrors.department}</p>
              )}
            </div>

            {/* Location */}
            <div>
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('location')} <span className="text-red-500 font-bold">*</span>
              </label>
              <input
                type="text"
                required
                aria-required="true"
                value={location}
                onChange={(e) => {
                  setLocation(e.target.value);
                  setFieldErrors(prev => ({ ...prev, location: '' }));
                }}
                placeholder={t('locationPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium transition-all"
              />
              {fieldErrors.location && (
                <p className="text-[11px] text-red-500 font-semibold mt-1 text-start">{fieldErrors.location}</p>
              )}
            </div>

            {/* Min Experience */}
            <div>
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('experienceYears')} <span className="text-red-500 font-bold">*</span>
              </label>
              <input
                type="number"
                required
                aria-required="true"
                min={0}
                value={experience}
                onChange={(e) => {
                  setExperience(parseInt(e.target.value) || 0);
                  setFieldErrors(prev => ({ ...prev, experience: '' }));
                }}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main focus:outline-none focus:border-brand text-xs font-semibold transition-all"
              />
              {fieldErrors.experience && (
                <p className="text-[11px] text-red-500 font-semibold mt-1 text-start">{fieldErrors.experience}</p>
              )}
            </div>

            {/* Required Degree Level */}
            <div>
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('degreeRequired')} <span className="text-red-500 font-bold">*</span>
              </label>
              <input
                type="text"
                required
                aria-required="true"
                value={degree}
                onChange={(e) => {
                  setDegree(e.target.value);
                  setFieldErrors(prev => ({ ...prev, degree: '' }));
                }}
                placeholder={t('degreeRequiredPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium transition-all"
              />
              {fieldErrors.degree && (
                <p className="text-[11px] text-red-500 font-semibold mt-1 text-start">{fieldErrors.degree}</p>
              )}
            </div>

            {/* Detailed Specialization */}
            <div>
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('specializationFormLabel')}
              </label>
              <input
                type="text"
                value={specialization}
                onChange={(e) => setSpecialization(e.target.value)}
                placeholder={t('specializationPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium transition-all"
              />
            </div>
          </div>
        </div>

        {/* Section 2: Requirements & Specifications */}
        <div className="bg-bg-card border border-border-main p-6 rounded-2xl space-y-4 shadow-sm">
          <div className="flex items-center gap-2 pb-2 border-b border-border-main/50">
            <Code className="w-4 h-4 text-amber-500" />
            <h3 className="text-xs font-bold text-text-muted uppercase tracking-wider">
              {t('sectionRequirements')}
            </h3>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Merged Single Skills Field */}
            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('coreSkills')}
              </label>
              <input
                type="text"
                value={skills}
                onChange={(e) => setSkills(e.target.value)}
                placeholder={t('coreSkillsPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium transition-all"
              />
            </div>

            {/* Required Certifications */}
            <div>
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('requiredCerts')}
              </label>
              <input
                type="text"
                value={requiredCerts}
                onChange={(e) => setRequiredCerts(e.target.value)}
                placeholder={t('requiredCertsPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium transition-all"
              />
            </div>

            {/* Required Nationality */}
            <div>
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('nationalityFormLabel')}
              </label>
              <input
                type="text"
                value={nationality}
                onChange={(e) => setNationality(e.target.value)}
                placeholder={t('nationalityPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium transition-all"
              />
            </div>

            {/* Languages */}
            <div>
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('languages')}
              </label>
              <input
                type="text"
                value={languages}
                onChange={(e) => setLanguages(e.target.value)}
                placeholder={t('languagesPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium transition-all"
              />
            </div>

            {/* Soft Skills */}
            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('softSkills')}
              </label>
              <input
                type="text"
                value={softSkills}
                onChange={(e) => setSoftSkills(e.target.value)}
                placeholder={t('softSkillsPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium transition-all"
              />
            </div>

            {/* General Job Description */}
            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('jobDescription')}
              </label>
              <textarea
                rows={4}
                value={jobDescription}
                onChange={(e) => {
                  setJobDescription(e.target.value);
                  handleAutoGrow(e);
                }}
                placeholder={t('jobDescriptionPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium resize-none transition-all text-start"
              />
            </div>

            {/* Core Responsibilities */}
            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('coreResponsibilities')}
              </label>
              <textarea
                rows={4}
                value={coreResponsibilities}
                onChange={(e) => {
                  setCoreResponsibilities(e.target.value);
                  handleAutoGrow(e);
                }}
                placeholder={t('coreResponsibilitiesPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium resize-none transition-all text-start"
              />
            </div>

            {/* Additional Requirements */}
            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-text-muted mb-1.5 px-1 text-start">
                {t('additionalRequirements')}
              </label>
              <textarea
                rows={4}
                value={additionalRequirements}
                onChange={(e) => {
                  setAdditionalRequirements(e.target.value);
                  handleAutoGrow(e);
                }}
                placeholder={t('additionalRequirementsPlaceholder')}
                className="w-full px-3.5 py-2.5 rounded-xl border border-border-main bg-bg-main/50 text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium resize-none transition-all text-start"
              />
            </div>
          </div>
        </div>

        {/* Section 3: Evaluation Weights / ATS Checklist */}
        <div className="bg-bg-card border border-border-main p-6 rounded-2xl space-y-4 shadow-sm">
          <div className="flex justify-between items-center pb-2 border-b border-border-main/50">
            <h3 className="text-xs font-bold text-text-muted uppercase tracking-wider flex items-center gap-1.5">
              <ListChecks className="w-4 h-4 text-brand" />
              {t('sectionChecklistInfo')}
            </h3>
            <button
              type="button"
              onClick={handleAddChecklistItem}
              className="flex items-center gap-1.5 text-xs text-brand hover:underline font-bold transition-all cursor-pointer"
            >
              <PlusCircle className="w-4 h-4" />
              <span>{t('addChecklistItem')}</span>
            </button>
          </div>

          {fieldErrors.checklist && (
            <p className="text-[11px] text-red-500 font-semibold text-start">{fieldErrors.checklist}</p>
          )}

          <div className="space-y-3">
            {checklist.map((item, idx) => (
              <div key={item.id} className="p-4 bg-bg-main/60 border border-border-main/50 rounded-xl space-y-2.5">
                <div className="flex justify-between items-center">
                  <span className="text-[10px] font-bold text-text-muted uppercase">
                    {t('item')} #{idx + 1}
                  </span>
                  <button
                    type="button"
                    onClick={() => handleRemoveChecklistItem(item.id)}
                    className="text-text-muted/70 hover:text-red-500 transition-colors p-1 cursor-pointer"
                    title="Remove item"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>

                <textarea
                  required
                  aria-required="true"
                  rows={4}
                  value={item.requirement}
                  onChange={(e) => {
                    handleChecklistTextChange(item.id, e.target.value);
                    handleAutoGrow(e);
                  }}
                  placeholder={t('requirementDescription')}
                  className="w-full p-3 rounded-xl border border-border-main bg-bg-card text-text-main placeholder-text-muted/40 focus:outline-none focus:border-brand text-xs font-medium resize-none transition-all text-start"
                />

                <div className="flex items-center justify-between gap-2 pt-1">
                  <span className="text-[10px] font-bold text-text-muted uppercase">{t('importanceLevel')}</span>
                  <select
                    value={item.importance}
                    onChange={(e) => handleChecklistImportanceChange(item.id, e.target.value)}
                    className="px-3 py-1.5 bg-bg-card rounded-xl border border-border-main text-text-main text-xs focus:outline-none focus:border-brand font-semibold cursor-pointer"
                  >
                    <option value="Mandatory">{t('importanceMandatory')}</option>
                    <option value="Important">{t('importanceImportant')}</option>
                    <option value="Additional">{t('importanceAdditional')}</option>
                  </select>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Submit & Cancel Action Buttons */}
        <div className="pt-2 flex items-center justify-end gap-3">
          <button
            type="button"
            onClick={() => navigate('/')}
            className="px-6 py-2.5 border border-border-main rounded-xl text-xs font-bold text-text-muted hover:text-text-main transition-colors cursor-pointer"
          >
            {t('cancel')}
          </button>
          <button
            type="submit"
            disabled={loading}
            className="px-8 py-2.5 bg-brand hover:bg-brand-hover text-white rounded-xl font-bold text-xs shadow-md shadow-brand/10 transition-all cursor-pointer"
          >
            {loading ? t('savingJob') : t('saveJob')}
          </button>
        </div>

      </form>
    </div>
  );
};

export default Jobs;
